export default defineConfig({
  test: {
    projects: ['packages/*', 'db', 'apps/api', 'apps/web'],
    coverage: {
      provider: 'v8',
      include: ['apps/*/src/**/*.{ts,tsx}', 'packages/*/src/**/*.{ts,js}'],
      exclude: [
        '**/*.test.{ts,tsx,js}',
        '**/__tests__/**',
        'apps/*/src/test/**',
        'packages/*/src/test/**',
        // Generated by `npm run db:types` from the migrations: types and one constants object.
        'packages/db-types/**',
      ],
      reporter: ['text-summary', 'json-summary'],
      thresholds: { lines: 100, branches: 100, functions: 100, statements: 100 },
    },
  },
});
